if (input.length === 0) process.exit(0);

const n = input[0];
const arr = input.slice(1, n + 1);

// Count initial ones
let initialOnes = 0;
for (let i = 0; i < n; i++) {
    if (arr[i] === 1) initialOnes++;
}

// Edge case: if all are 1s, flipping any segment will reduce ones by at least 1
if (initialOnes === n) {
    console.log(n - 1);
    process.exit(0);
}

// Transform array: 0 -> +1, 1 -> -1
// We want maximum subarray sum (Kadane's algorithm)
let maxGain = -Infinity;
let currentGain = 0;

for (let i = 0; i < n; i++) {
    const val = (arr[i] === 0) ? 1 : -1;
    currentGain = Math.max(val, currentGain + val);
    maxGain = Math.max(maxGain, currentGain);
}

const result = initialOnes + maxGain;
