let maxGain = -Infinity;
let current = 0;

for (let val of transformed) {
    current = Math.max(val, current + val);
    maxGain = Math.max(maxGain, current);
}

// Edge case: all ones, flipping any segment reduces ones by at least 1
if (totalOnes === n) {
    console.log(n - 1);
} else {
    console.log(totalOnes + maxGain);
