const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (input.length === 0) process.exit(0);

const n = input[0];
const arr = input.slice(1, n + 1);

let totalOnes = 0;
for (let i = 0; i < n; i++) {
    if (arr[i] === 1) totalOnes++;
}

let maxGain = -Infinity;
for (let i = 0; i < n; i++) {
    let gain = 0;
    for (let j = i; j < n; j++) {
        if (arr[j] === 0) gain += 1;
        else gain -= 1;
        if (gain > maxGain) maxGain = gain;
    }
}

const result = totalOnes + maxGain;
